-- Study Abroad country content, BATCH 6: Belgium, Norway, Czechia, Hungary, Greece.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('belgium', 'norway', 'czechia', 'hungary', 'greece'));
UPDATE countries SET why_title = 'Why study in Belgium?', why_body = '<p>Belgium is at the centre of Europe and hosts the main EU institutions. Its universities teach in Dutch, French and English, and are known for research, engineering, law and international relations.</p><ul><li>Respected research universities such as KU Leuven and Ghent University</li><li>Many English-taught Master''s programmes</li><li>Brussels is home to the EU and NATO, which is useful for law, policy and international relations careers</li><li>Easy travel to Paris, Amsterdam, London and Cologne</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-EU students need a <strong>type D long-stay visa</strong> for study, then a residence permit after arrival. Your university must register you and give you an admission document first.</p><ul><li>Admission or enrolment certificate from a Belgian institution</li><li>Proof of funds: the minimum for 2026-27 is reported at about €1,062 a month (some universities quote €1,100), usually shown through a blocked account, a guarantor or a scholarship</li><li>Health insurance valid in Belgium</li><li>Medical certificate and criminal record extract, legalised where required</li><li>The residence permit is usually valid for one academic year plus one month and is renewed each year with proof of funds</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Belgian Immigration Office and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. Master''s deadlines for non-EU students are often earlier than for EU students.</p><ul><li>Academic transcripts and certificates, legalised or apostilled</li><li>Language proof (English, Dutch or French)</li><li>Motivation letter and CV</li><li>Letters of recommendation for some Master''s programmes</li><li>Entrance exam or portfolio for some programmes</li><li>Passport copy</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition for non-EU students depends on the region and institution. Brussels and Leuven are more expensive than smaller cities.</p><ul><li>Tuition (non-EU): in Flanders often about €3,000-€9,000 a year, depending on the programme (reported range)</li><li>Living costs: about €1,000-€1,300 a month, matching the visa funds guide</li><li>Student housing is limited, so apply early</li><li>Health insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the institution and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school diploma recognised in Belgium, sometimes with an entrance exam (for example for medicine and engineering)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof (IELTS 6.0-6.5) or Dutch/French proof for local-language courses</li><li>Students may need an equivalence decision for foreign diplomas</li></ul>' WHERE slug = 'belgium';
UPDATE countries SET why_title = 'Why study in Norway?', why_body = '<p>Norway has strong public universities, high living standards and expertise in energy, maritime, marine and environmental fields. Many Master''s programmes are taught in English.</p><ul><li>Strong in energy, offshore, maritime and aquaculture fields</li><li>Teaching in small groups with close contact with teachers</li><li>PhD positions are salaried jobs, with no tuition</li><li>Beautiful natural environment and a very safe society</li></ul>', visa_title = 'Student residence permit requirements', visa_body = '<p>Non-EU students need a <strong>study permit</strong> from the Norwegian Directorate of Immigration (UDI). You apply online and then present documents at a visa application centre or police station.</p><ul><li>Admission letter from a Norwegian institution</li><li>Proof of funds: UDI sets a yearly amount; recent figures are about NOK 150,000-170,000 per year (the newest amount is published each year, so check UDI)</li><li>Proof of tuition payment, if required</li><li>Accommodation proof and passport</li><li>Work: students may work part time (usually up to 20 hours a week)</li><li>Graduates may apply for a job-seeker permit (check the current length)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official UDI (udi.no) site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Most Bachelor''s and Master''s applications go through <strong>Søknadsweb</strong> or each university''s portal, with firm deadlines (often in December-March).</p><ul><li>Academic transcripts and certificates, with translations</li><li>English proficiency proof (IELTS or TOEFL)</li><li>Motivation letter and CV</li><li>Letters of recommendation for some Master''s programmes</li><li>Passport copy</li><li>Proof of funds for the study permit</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition for non-EU students was introduced at public universities, and living costs are high.</p><ul><li>Tuition (non-EU): roughly NOK 100,000-200,000 a year, depending on the university and programme (estimate; check each university)</li><li>Living costs: UDI guide of about NOK 150,000-170,000 per year</li><li>Semester fee: a small student welfare fee of about NOK 600-1,000 per semester</li><li>Health: students may join the Norwegian health system when they qualify</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the programme.</p><ul><li><strong>Bachelor''s:</strong> general university admissions certificate, with higher requirements from some countries (for example one year of university study)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree, usually 3 years</li><li><strong>English:</strong> IELTS 6.5 or TOEFL 90 for most programmes</li><li>Applicants must meet the funds and deadline rules</li></ul>' WHERE slug = 'norway';
UPDATE countries SET why_title = 'Why study in the Czech Republic?', why_body = '<p>The Czech Republic offers affordable study in the heart of Europe, with old universities, English-taught programmes and free tuition for programmes taught in Czech at public universities.</p><ul><li>Free tuition at public universities for Czech-taught programmes</li><li>English-taught programmes in medicine, engineering, computing and business</li><li>Prague is a leading student city, with lower costs than most Western European capitals</li><li>Charles University and Czech Technical University are internationally known</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-EU students planning to study longer than 90 days apply for a <strong>long-term visa for study</strong> at a Czech embassy, and then a residence permit after arrival.</p><ul><li>Confirmation of study from the Czech university</li><li>Proof of funds: a third-party guide reports about CZK 124,500 for a year (it follows the subsistence minimum; check the Interior Ministry page)</li><li>Travel and health insurance valid in the Czech Republic</li><li>Criminal record extract and medical certificate</li><li>Proof of accommodation</li><li>Processing can take 60-90 days, so apply early</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Czech Ministry of Foreign Affairs site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, and some programmes require entrance exams.</p><ul><li>Academic transcripts and certificates, with nostrification (recognition) of school certificates where required</li><li>Language proof (English or Czech)</li><li>Motivation letter and CV for Master''s programmes</li><li>Entrance exams for medicine, dentistry and some other courses</li><li>Passport copy</li><li>Application fee at some universities</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Czech-taught programmes at public universities are free, while English-taught programmes charge tuition. Living costs are low compared with Western Europe.</p><ul><li>Tuition (English-taught): roughly CZK 100,000-400,000 a year (reported), and medicine is at the high end</li><li>Czech-taught public programmes: free, but you must pass a Czech language test</li><li>Living costs: about CZK 15,000-25,000 a month; Prague is more expensive</li><li>Health insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and programme.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate recognised in the Czech Republic; many programmes have entrance exams</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof (IELTS 5.5-6.5) or Czech (B2) for Czech-taught courses</li><li>Medicine needs biology and chemistry exams</li></ul>' WHERE slug = 'czechia';
UPDATE countries SET why_title = 'Why study in Hungary?', why_body = '<p>Hungary offers affordable English-taught degrees, especially in medicine, dentistry and engineering, and runs one of the largest scholarship programmes in Europe, <strong>Stipendium Hungaricum</strong>.</p><ul><li>English-taught medicine, dentistry and pharmacy programmes with a long tradition</li><li>Stipendium Hungaricum scholarships cover tuition and give a monthly stipend</li><li>Budapest is a lower-cost capital with a vibrant student life</li><li>Located in central Europe, close to Vienna and Prague</li></ul>', visa_title = 'Student visa and residence permit requirements', visa_body = '<p>Non-EU students enter with a <strong>national D visa for study</strong> and then apply for a <strong>residence permit for study</strong> through the Hungarian immigration authority (OIN) after arrival.</p><ul><li>Admission letter from a Hungarian institution</li><li>Proof of funds: about HUF 200,000 a month (roughly €500) in third-party guides, or a scholarship such as Stipendium Hungaricum</li><li>Health insurance valid in Hungary</li><li>Accommodation proof, passport and photographs</li><li>Stipendium Hungaricum holders get free visa and residence permit administration</li><li>Renew the residence permit at least 30 days before it expires</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Hungarian embassy and OIN site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, or through <strong>Stipendium Hungaricum</strong> if you are applying for the scholarship (deadlines are usually in the winter before the autumn intake).</p><ul><li>Academic transcripts and certificates, often apostilled</li><li>English proficiency proof</li><li>Motivation letter and CV</li><li>Entrance exam or interview for medicine and some other courses</li><li>Passport copy and medical certificate</li><li>Scholarship applications go through your home country''s national authority</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the programme. Medicine and dentistry cost more than other fields, and scholarship holders at public universities pay no tuition.</p><ul><li>Tuition (self-funded): about €2,000-€8,000 a year for most non-medical programmes, and about €8,000-€18,000 for English-taught medicine (reported ranges)</li><li>Living costs: about €500-€800 a month; Budapest is more expensive</li><li>Stipendium Hungaricum covers tuition, a monthly stipend and accommodation support</li><li>Health insurance is required unless covered by a scholarship</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the programme.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with strong marks; medicine needs biology and chemistry exams</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>English:</strong> IELTS 5.5-6.5 or equivalent</li><li>Stipendium Hungaricum applicants must come from partner countries and meet academic and age rules</li></ul>' WHERE slug = 'hungary';
UPDATE countries SET why_title = 'Why study in Greece?', why_body = '<p>Greece offers historic universities, a warm climate and lower costs than most Western European countries. It is a good choice for archaeology, classics, tourism, shipping and architecture.</p><ul><li>Lower tuition and living costs than many European countries</li><li>English-taught Master''s programmes at public universities</li><li>World-leading shipping industry and a strong tourism and hospitality sector</li><li>Rich history and culture</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Non-EU students apply for a <strong>national type D student visa</strong> at the Greek consulate, then apply for a <strong>residence permit</strong> after arrival.</p><ul><li>Admission letter or enrolment certificate from a Greek institution</li><li>Proof of funds: guides report about €650 a month, or about €7,000-€8,000 a year</li><li>Private health insurance valid in Greece</li><li>Criminal record certificate and passport</li><li>Residence permit application: apply at the local immigration service after arrival</li><li>Work: students on a permit may work up to 20 hours a week with the right permission</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Greek consulate and the Ministry of Migration site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Most Greek public universities take international applications for English-taught Master''s programmes directly. Many Bachelor''s degrees are taught in Greek.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English proof (IELTS or equivalent)</li><li>CV and motivation letter</li><li>Letters of recommendation for Master''s</li><li>Passport copy</li><li>Greek language certificate for Greek-taught courses</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition for non-EU students applies to English-taught programmes at public universities, and private colleges charge more.</p><ul><li>Tuition (non-EU): reported at about €1,500-€7,000 a year at public universities</li><li>Private colleges: roughly €4,000-€10,000+ a year</li><li>Living costs: about €600-€900 a month; Athens is more expensive</li><li>Private health insurance is required for the residence permit</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the institution and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; Greek-taught courses need Greek language proof</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>English:</strong> IELTS 6.0 or equivalent for English-taught courses</li><li>Some programmes require an interview or portfolio</li></ul>' WHERE slug = 'greece';
COMMIT;
